// Build the list of feeds to fetch.
// Two source types:
//   - kijiji / kijiji-house: r.jina.ai-fetched markdown from Kijiji category pages
//   - searxng-fb: SearXNG meta-search query that returns indexed FB Marketplace
//                 listings via Google/DuckDuckGo (rich snippets, no FB login needed)
//
// The Jina/Fetch HTTP node downstream uses item.json.fetch_url, which is
// pre-built here so the HTTP node stays source-agnostic.

const kijijiFeeds = [
  // Kijiji long-term rentals by neighborhood
  { source: 'kijiji', neighborhood: 'rosemont',       kijiji_url: 'https://www.kijiji.ca/b-appartement-condo/grand-montreal/rosemont/k0c37l80002' },
  { source: 'kijiji', neighborhood: 'mile-end',       kijiji_url: 'https://www.kijiji.ca/b-appartement-condo/grand-montreal/mile-end/k0c37l80002' },
  { source: 'kijiji', neighborhood: 'plateau',        kijiji_url: 'https://www.kijiji.ca/b-appartement-condo/grand-montreal/plateau-mont-royal/k0c37l80002' },
  { source: 'kijiji', neighborhood: 'villeray',       kijiji_url: 'https://www.kijiji.ca/b-appartement-condo/grand-montreal/villeray/k0c37l80002' },
  { source: 'kijiji', neighborhood: 'petite-italie',  kijiji_url: 'https://www.kijiji.ca/b-appartement-condo/grand-montreal/petite-italie/k0c37l80002' },
  { source: 'kijiji', neighborhood: 'outremont',      kijiji_url: 'https://www.kijiji.ca/b-appartement-condo/grand-montreal/outremont/k0c37l80002' },
  // FIXED 2026-04-09: c43l1700281 was a dead category code, c34 (real estate) works
  { source: 'kijiji-house', neighborhood: 'maison-louer-mtl', kijiji_url: 'https://www.kijiji.ca/b-real-estate/grand-montreal/maison-a-louer/k0c34l80002' },
  // Bungalow keyword feed — mostly suburb noise that the location_reject filter drops,
  // but catches the rare in-zone bungalow when one appears (peak listings: mid-May for July 1)
  { source: 'kijiji-house', neighborhood: 'bungalow-mtl', kijiji_url: 'https://www.kijiji.ca/b-real-estate/grand-montreal/bungalow/k0c34l80002' },
];

// SearXNG meta-search for FB Marketplace listings via Google/DuckDuckGo index.
// Each query returns ~10 results with rich snippets (title + URL + 200-400 char
// content). No FB login required because we never touch facebook.com directly.
// Trade-off: search-engine index lag means brand-new listings appear here days
// to weeks AFTER they hit Kijiji. Use both feeds together for best coverage.
// Reduced from 7 to 3 queries because SearXNG queries to Google/DuckDuckGo
// get rate-limited when fired in rapid succession (only the first 1-2 return
// data, the rest return empty envelopes). 3 queries is the empirical sweet spot.
const searxngQueries = [
  { neighborhood: 'rosemont',         query: 'site:facebook.com/marketplace montreal rosemont property rentals' },
  { neighborhood: 'mile-end',         query: 'site:facebook.com/marketplace montreal "mile end" property rentals' },
  { neighborhood: 'rosemont-maison',  query: 'site:facebook.com/marketplace montreal maison louer rosemont' },
];

const feeds = [];

for (const f of kijijiFeeds) {
  feeds.push({
    source: f.source,
    neighborhood: f.neighborhood,
    url: f.kijiji_url,
    fetch_url: 'https://r.jina.ai/' + f.kijiji_url,
  });
}

for (const f of searxngQueries) {
  feeds.push({
    source: 'searxng-fb',
    neighborhood: f.neighborhood,
    // synthetic url for dedup tracking — not a real fetch target
    url: 'searxng-fb://' + encodeURIComponent(f.query),
    query: f.query,
    fetch_url: 'http://searxng:8080/search?q=' + encodeURIComponent(f.query) + '&format=json',
  });
}

return feeds.map(f => ({ json: f }));

// Parse fetched feed bodies into normalized listing objects.
// Dispatches on source pulled from Build Feed List by index (the Jina Reader
// HTTP node strips the original feed metadata from item.json, so we have to
// recover it from the upstream node by position).

const fetchedBodies = $input.all();           // outputs from Jina Reader (one per feed)
const feedItems = $('Build Feed List').all(); // original feeds with source/url/query

const out = [];

const WORD_NUMS_EN = { one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8 };
const WORD_NUMS_FR = { un: 1, une: 1, deux: 2, trois: 3, quatre: 4, cinq: 5, six: 6, sept: 7, huit: 8 };

function parseBedsFromText(text) {
  if (!text) return null;
  const found = [];
  for (const m of text.matchAll(/(\d+)\s*[-\s]?\s*(?:bed(?:room)?s?|br)\b/gi)) found.push(parseInt(m[1], 10));
  for (const m of text.matchAll(/(\d+)\s*chambres?\b/gi)) found.push(parseInt(m[1], 10));
  for (const m of text.matchAll(/\b(one|two|three|four|five|six|seven|eight)[-\s]+(?:bed|br)/gi)) found.push(WORD_NUMS_EN[m[1].toLowerCase()]);
  for (const m of text.matchAll(/\b(un|une|deux|trois|quatre|cinq|six|sept|huit)\s+chambres?/gi)) found.push(WORD_NUMS_FR[m[1].toLowerCase()]);
  for (const m of text.matchAll(/(\d+)(?:[-\s]*(?:1\/2|½|⅟)|\s*et\s*(?:demi|1\/2|½))/gi)) {
    const r = parseInt(m[1], 10);
    if (!isNaN(r)) found.push(Math.max(0, r - 2));
  }
  if (found.length === 0) return null;
  return Math.max(...found);
}

function parseBathsFromText(text) {
  if (!text) return null;
  const found = [];
  for (const m of text.matchAll(/(\d+(?:[.,]\d+)?)\s*(?:bath(?:room)?s?|sdb|salle\s*de\s*bain)/gi)) {
    found.push(parseFloat(m[1].replace(',', '.')));
  }
  if (found.length === 0) return null;
  return Math.max(...found);
}

function parsePriceFromText(text) {
  if (!text) return null;
  const candidates = [];
  for (const m of text.matchAll(/\$?\s*(\d{1,2}[,\s.]?\d{3})(?:[.,]\d{2})?\s*(?:\$|\/?\s*mois|\/?\s*mo|per\s*month)/gi)) {
    const n = parseFloat(m[1].replace(/[,\s.]/g, ''));
    if (n >= 500 && n <= 10000) candidates.push(n);
  }
  for (const m of text.matchAll(/\$\s*(\d{1,2}[,\s.]?\d{3})(?:[.,]\d{2})?/g)) {
    const n = parseFloat(m[1].replace(/[,\s.]/g, ''));
    if (n >= 500 && n <= 10000) candidates.push(n);
  }
  if (candidates.length === 0) return null;
  return Math.min(...candidates);
}

function detectLocationFromText(text) {
  if (!text) return '';
  const hoods = [
    ['Rue Masson', 'Rue Masson, Rosemont'],
    ['Vieux Rosemont', 'Vieux Rosemont, Montréal'],
    ['Old Rosemont', 'Old Rosemont, Montréal'],
    ['Petite-Patrie', 'Petite-Patrie, Montréal'],
    ['Petite Patrie', 'Petite-Patrie, Montréal'],
    ['Rosemont', 'Rosemont, Montréal'],
    ['Mile End', 'Mile End, Montréal'],
    ['Mile-End', 'Mile End, Montréal'],
    ['Plateau', 'Plateau, Montréal'],
    ['Villeray', 'Villeray, Montréal'],
    ['Outremont', 'Outremont, Montréal'],
    ['Petite Italie', 'Petite Italie, Montréal'],
    ['Little Italy', 'Little Italy, Montréal'],
    ['Parc-Extension', 'Parc-Extension, Montréal'],
    ['Jarry Park', 'Jarry Park, Montréal'],
    ['De Lorimier', 'De Lorimier, Montréal'],
    ['Maisonneuve Park', 'Maisonneuve Park, Montréal'],
  ];
  const lower = text.toLowerCase();
  for (const [needle, label] of hoods) {
    if (lower.includes(needle.toLowerCase())) return label;
  }
  return '';
}

// Iterate fetched bodies, look up source by index
for (let i = 0; i < fetchedBodies.length; i++) {
  const fetchedItem = fetchedBodies[i];
  // Recover the original feed metadata by position
  const feedItem = feedItems[i] ? feedItems[i].json : {};
  const source = feedItem.source || 'kijiji';
  const feedHood = feedItem.neighborhood || '';

  // ---------- SearXNG → FB Marketplace branch ----------
  if (source === 'searxng-fb') {
    const raw = fetchedItem.json.data || fetchedItem.json.body || fetchedItem.json;
    let parsed;
    try {
      parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
    } catch (e) { continue; }
    const results = parsed && parsed.results ? parsed.results : [];

    for (const r of results) {
      const url = r.url || '';
      if (!/facebook\.com\/marketplace\/item\//.test(url)) continue;

      const titleRaw = r.title || '';
      if (/for\s*sale/i.test(titleRaw) || /à\s*vendre/i.test(titleRaw)) continue;
      const content = r.content || '';
      if (/\$\s*\d{3}[,\s.]\d{3}/.test(titleRaw + ' ' + content)) continue;

      const title = titleRaw
        .replace(/\s*-\s*Property Rentals.*$/i, '')
        .replace(/\s*\|\s*Facebook.*$/i, '')
        .replace(/\s*-\s*Montreal,?\s*Quebec.*$/i, '')
        .trim();

      const corpus = title + ' ' + content;
      const beds = parseBedsFromText(corpus);
      const baths = parseBathsFromText(corpus);
      const price = parsePriceFromText(corpus);
      const location = detectLocationFromText(corpus);

      out.push({
        json: {
          source: 'searxng-fb',
          feed_neighborhood: feedHood,
          title,
          url,
          image_url: null,
          price,
          beds,
          baths,
          sqft: null,
          property_type: null,
          location,
          description: content.slice(0, 400),
          description_full: content.slice(0, 1500),
          days_ago: null,
          fetched_at: new Date().toISOString(),
        }
      });
    }
    continue;
  }

  // ---------- Kijiji markdown branch ----------
  const md = fetchedItem.json.data || fetchedItem.json.body || fetchedItem.json;
  const text = typeof md === 'string' ? md : JSON.stringify(md);

  const cardRe = /### \[(.+?)\]\((https?:\/\/[^)]+)\)([\s\S]*?)(?=### \[|$)/g;
  let m;
  while ((m = cardRe.exec(text)) !== null) {
    const title = m[1].replace(/\*\*/g, '').trim();
    const url = m[2].split('?')[0];
    const body = m[3];

    if (!/kijiji\.ca\/v-/.test(url)) continue;

    const before = text.slice(Math.max(0, m.index - 600), m.index);
    const imgMatches = [...before.matchAll(/!\[Image \d+:[^\]]*\]\((https?:\/\/[^)]+)\)/g)];
    const image_url = imgMatches.length ? imgMatches[imgMatches.length - 1][1] : null;
    const priceM = [...before.matchAll(/\$([\d,]+(?:\.\d{2})?)/g)].pop();
    const price = priceM ? parseFloat(priceM[1].replace(/,/g, '')) : null;

    const daysM = body.match(/(\d+)\s*d(?:\s|$)/);
    const daysAgo = daysM ? parseInt(daysM[1], 10) : null;

    const lines = body.split('\n');
    const bullets = [];
    for (const line of lines) {
      const bm = line.match(/^\s*\*\s+(.+)$/);
      if (bm) bullets.push(bm[1].replace(/\*\*/g, '').trim());
    }
    const uniqueBullets = [];
    for (const b of bullets) {
      if (uniqueBullets[uniqueBullets.length - 1] !== b) uniqueBullets.push(b);
    }

    let beds = null, baths = null, propType = null, sqft = null;
    if (uniqueBullets.length >= 5) {
      const num0 = parseInt(uniqueBullets[0], 10);
      const num1 = parseFloat(uniqueBullets[1].replace(',', '.'));
      if (!isNaN(num0) && num0 < 20) beds = num0;
      if (!isNaN(num1) && num1 < 20) baths = num1;
      propType = uniqueBullets[2] || null;
      const sqftM = uniqueBullets[4] && uniqueBullets[4].match(/(\d+)\s*sqft/i);
      if (sqftM) sqft = parseInt(sqftM[1], 10);
    }

    const proseLines = lines.filter(l => !/^\s*\*\s+/.test(l));
    const prose = proseLines.join('\n').replace(/\*\*/g, '').replace(/\s+/g, ' ').trim();
    const description = prose.slice(0, 1500);

    if (beds === null) beds = parseBedsFromText(title + ' ' + description);
    if (baths === null) baths = parseBathsFromText(title + ' ' + description);

    const locM = body.match(/\n([^\n•]+),\s*([^\n•]+)\n[\s\S]*?•/);
    const location = locM ? `${locM[1].trim()}, ${locM[2].trim()}` : '';

    if (price === null) continue;

    out.push({
      json: {
        source,
        feed_neighborhood: feedHood,
        title,
        url,
        image_url,
        price,
        beds,
        baths,
        sqft,
        property_type: propType,
        location,
        description: description.slice(0, 400),
        description_full: description,
        days_ago: daysAgo,
        fetched_at: new Date().toISOString(),
      }
    });
  }
}

return out;

// Dedup + hard filter.
// Reads preferences.json and seen.json directly from disk via fs because
// n8n's binary-data-via-base64-decode trick is unreliable in 2.x and was
// silently returning null for the entire day, which made the location_reject
// list never fire. Direct fs read is bulletproof — container has
// NODE_FUNCTION_ALLOW_BUILTIN=* so require('fs') works.

const fs = require('fs');

const PREFS_PATH = '/data/shared/rentals/preferences.json';
const SEEN_PATH  = '/data/shared/rentals/seen.json';

let prefs;
try {
  prefs = JSON.parse(fs.readFileSync(PREFS_PATH, 'utf8'));
} catch (e) {
  // Fallback to safe defaults if the file is missing/corrupt
  prefs = {
    max_price: 3200, ideal_price: 2800,
    min_bedrooms: 3, min_bathrooms: 1.5,
    location_allow: [], location_reject: [],
    likes: [], dislikes: []
  };
}

let seen;
try {
  seen = JSON.parse(fs.readFileSync(SEEN_PATH, 'utf8'));
} catch (e) {
  seen = { urls: {} };
}
if (!seen.urls) seen.urls = {};

const rejectList = (prefs.location_reject || []).map(s => s.toLowerCase());

function isSingleRoomRental(title) {
  const t = (title || '').toLowerCase().trim();
  if (/^chambre\b/.test(t) && !/^chambres\b/.test(t)) return true;
  if (/\broom\s+(for\s+rent|available|wanted)\b/.test(t)) return true;
  if (/\b(roommate|colocataire|colocation)\b/.test(t)) return true;
  if (/\bsublet\s+room\b/.test(t)) return true;
  return false;
}

function locationVerdict(listing) {
  const corpus = [
    listing.location || '',
    listing.title || '',
    listing.url || '',
    listing.description_full || ''
  ].join(' ').toLowerCase();
  for (const bad of rejectList) {
    if (bad && corpus.includes(bad)) return { ok: false, reason: 'loc_reject:' + bad };
  }
  return { ok: true };
}

const listings = $input.all().map(it => it.json).filter(j => j && j.url && j.price !== undefined);
const total = listings.length;
const newOnes = listings.filter(l => !seen.urls[l.url]);

const skipped = { price: 0, beds: 0, location: 0, single_room: 0 };
const filtered = [];
for (const l of newOnes) {
  if (l.price == null || l.price > prefs.max_price) { skipped.price++; continue; }
  if (l.beds != null && l.beds < prefs.min_bedrooms) { skipped.beds++; continue; }
  if (isSingleRoomRental(l.title)) { skipped.single_room++; continue; }
  const lv = locationVerdict(l);
  if (!lv.ok) { skipped.location++; continue; }
  filtered.push(l);
}

const staticData = $getWorkflowStaticData('node');
staticData.prefs = prefs;
staticData.runSummary = {
  total_today: total,
  new_count: newOnes.length,
  filtered_count: filtered.length,
  skipped,
  prefs_loaded_from: PREFS_PATH,
  reject_terms_loaded: rejectList.length,
  run_at: new Date().toISOString()
};
staticData.priorSeen = seen;

return filtered.map(l => ({ json: l }));

// Merge Gemma's response back into each listing item.
// HTTP Request node replaces the item with the response, so we walk back via
// $('Build Gemma Prompt').all() which still has the listing data + prompt.
// Order is preserved by n8n's executionOrder=v1, so index alignment is safe.

const gemmaItems = $input.all();
const listings = $('Build Gemma Prompt').all();

const out = [];
for (let i = 0; i < listings.length; i++) {
  // Drop the prompt field from the listing — it was only used for the API call
  const { prompt, ...listing } = listings[i].json;
  const gemmaResp = gemmaItems[i]?.json;

  let llm = null;
  try {
    if (gemmaResp && gemmaResp.response) {
      llm = JSON.parse(gemmaResp.response);
    }
  } catch (e) {
    llm = null;
  }

  listing.llm = llm;
  listing.llm_score = llm?.score ?? null;
  out.push({ json: listing });
}

return out;

// Final ranker: combine heuristic score + Gemma score, sort, assign L# tags, format email.

const items = $input.all();
const staticData = $getWorkflowStaticData('node');
const prefs = staticData.prefs || { max_price: 3500, ideal_price: 2800, min_bedrooms: 3, min_bathrooms: 1.5, soft_signals: {}, neighborhood_weights: {}, likes: [], dislikes: [] };
const run = staticData.runSummary || { total_today: 0, new_count: 0, filtered_count: 0, run_at: new Date().toISOString() };

function heuristicScore(l, prefs) {
  let score = 0;
  const reasons = [];
  if (l.price <= prefs.ideal_price) {
    score += 50;
    reasons.push(`price≤ideal (+50)`);
  } else {
    const room = prefs.max_price - prefs.ideal_price;
    const overshoot = l.price - prefs.ideal_price;
    const ps = Math.max(0, 50 * (1 - overshoot / room));
    score += ps;
    reasons.push(`price ${l.price} (+${ps.toFixed(1)})`);
  }
  if (l.beds != null && l.beds > prefs.min_bedrooms) {
    score += 5 * (l.beds - prefs.min_bedrooms);
  }
  if (l.baths != null && l.baths >= prefs.min_bathrooms) score += 5;
  const haystack = `${l.title} ${l.description}`.toLowerCase();
  const sig = {
    garage_or_parking: /garage|stationnement|parking/i,
    basement: /sous-sol|basement|sous sol/i,
    backyard: /cour|backyard|terrasse|jardin priv|yard/i,
    ground_floor: /rez-de-chauss|ground floor|rdc|rdj/i,
    renovated: /r[ée]nov[ée]|renovated|refait/i,
    near_park: /parc |park |botaniqu|maisonneuve|lafontaine|laurier/i,
    near_market: /jean-talon|atwater|march[ée]/i,
    cafe_neighborhood: /caf[ée]|restaurant|boutique|shops/i,
    metro_walk: /m[ée]tro|metro|station/i,
  };
  for (const [k, re] of Object.entries(sig)) {
    if (re.test(haystack)) {
      const w = (prefs.soft_signals && prefs.soft_signals[k]) || 1;
      score += 5 * w;
    }
  }
  if (prefs.neighborhood_weights) {
    for (const [hood, weight] of Object.entries(prefs.neighborhood_weights)) {
      if (haystack.includes(hood) || (l.location || '').toLowerCase().includes(hood)) {
        score += 10 * weight;
        break;
      }
    }
  }
  for (const like of (prefs.likes || [])) {
    if (haystack.includes(String(like).toLowerCase())) score += 8;
  }
  for (const dis of (prefs.dislikes || [])) {
    if (haystack.includes(String(dis).toLowerCase())) score -= 12;
  }
  return Math.round(score * 10) / 10;
}

// Combine: 60% LLM (when available) + 40% heuristic. If LLM missing, 100% heuristic.
const scored = items.map(it => {
  const l = { ...it.json };
  const heur = heuristicScore(l, prefs);
  l.heuristic_score = heur;
  if (l.llm_score != null) {
    l.final_score = Math.round(0.6 * l.llm_score + 0.4 * heur);
  } else {
    l.final_score = Math.round(heur);
  }
  return l;
});

scored.sort((a, b) => b.final_score - a.final_score);
scored.forEach((l, i) => { l.tag = `L${i + 1}`; });

// French-leak guard: qwen3 occasionally copies French prose verbatim.
// Used below to drop title/description when common French words appear.
const frenchRe = /\b(chambres?|appartement|cuisine|rénové|pi[èe]ces?|sous-sol|salle\s+de\s+bain|maison|disponible|à\s+louer|jardin|é?lectrom[eé]nagers|pi[èe]ds?|idealement)\b/i;

const today = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Toronto' });

if (scored.length === 0) {
  return [{ json: {
    subject: `🏠 Rental Watcher — nothing new — ${today}`,
    body_html: `<p><em>Scanned ${run.total_today} listings, ${run.new_count} new, 0 matched filters today.</em></p><p>Filters: ≥3 BR, ≤ \$3500/mo, in target neighborhoods.</p>`,
    send: false,
    new_urls: []
  } }];
}

// Build HTML email body with images
let html = '';
html += `<div style="font-family:-apple-system,Helvetica,Arial,sans-serif;max-width:680px;margin:0 auto;color:#222">`;
html += `<h1 style="font-size:22px;margin:0 0 4px 0">🏠 ${scored.length} new rental match${scored.length === 1 ? '' : 'es'} — ${today}</h1>`;
html += `<p style="color:#666;font-size:13px;margin:0 0 18px 0">Scanned ${run.total_today} listings · ${run.new_count} new · ${scored.length} passed filters. Reply with thumbs to train tomorrow's ranking — e.g. <code>L2 👍</code> or <code>L4 👎 too far from metro</code>.</p>`;
html += `<hr style="border:none;border-top:1px solid #eee;margin:0 0 20px 0">`;

for (const l of scored) {
  const beds = l.beds != null ? `${l.beds} BR` : '? BR';
  const baths = l.baths != null ? ` · ${l.baths} bath` : '';
  const sqft = l.sqft != null ? ` · ${l.sqft} sqft` : '';
  const days = l.days_ago != null ? ` · ${l.days_ago}d ago` : '';
  const ptype = l.property_type ? ` · ${l.property_type}` : '';

  html += `<div style="margin-bottom:32px;padding-bottom:20px;border-bottom:1px solid #eee">`;
  html += `<div style="display:flex;align-items:baseline;gap:10px;margin-bottom:6px">`;
  html += `<span style="background:#f0f0f0;color:#333;padding:2px 8px;border-radius:4px;font-weight:600;font-size:13px">${l.tag}</span>`;
  html += `<span style="font-size:20px;font-weight:700;color:#0a0">$${l.price.toLocaleString()}/mo</span>`;
  html += `<span style="color:#888;font-size:13px">score ${l.final_score}${l.llm_score != null ? ` (LLM ${l.llm_score})` : ''}</span>`;
  html += `</div>`;
  html += `<h2 style="font-size:17px;margin:4px 0 6px 0;font-weight:600"><a href="${l.url}" style="color:#0066cc;text-decoration:none">${((l.llm && l.llm.title_en && !frenchRe.test(l.llm.title_en)) ? l.llm.title_en : (l.title && !frenchRe.test(l.title)) ? l.title : "(see listing →)")}</a></h2>`;
  html += `<div style="color:#555;font-size:13px;margin-bottom:10px"><strong>${beds}${baths}${sqft}${ptype}</strong>${days}${l.location ? ' · 📍 ' + l.location : ''}</div>`;

  if (l.image_url) {
    html += `<a href="${l.url}"><img src="${l.image_url}" alt="${l.title}" style="max-width:100%;border-radius:6px;margin-bottom:10px;display:block" /></a>`;
  }

  if (l.llm && l.llm.verdict) {
    html += `<p style="font-size:14px;font-style:italic;color:#444;margin:6px 0 8px 0">💬 ${l.llm.verdict}</p>`;
  }
  if (l.llm && l.llm.highlights && l.llm.highlights.length) {
    html += `<div style="font-size:13px;margin:6px 0"><strong style="color:#0a0">+</strong> ${l.llm.highlights.join(' · ')}</div>`;
  }
  if (l.llm && l.llm.concerns && l.llm.concerns.length) {
    html += `<div style="font-size:13px;margin:6px 0"><strong style="color:#c33">−</strong> ${l.llm.concerns.join(' · ')}</div>`;
  }
  const descEn = (l.llm && l.llm.description_en) ? l.llm.description_en : null;
  if (descEn && !frenchRe.test(descEn)) {
    html += `<p style="font-size:13px;color:#666;margin:8px 0 0 0">${descEn.replace(/</g, '&lt;')}</p>`;
  }
  html += `<p style="font-size:12px;margin:10px 0 0 0"><a href="${l.url}" style="color:#0066cc">${l.url}</a></p>`;
  html += `</div>`;
}

html += `<p style="font-size:11px;color:#999;margin-top:20px">Sources: Kijiji category pages via r.jina.ai. LLM: qwen3:14b on brains-mac-mini. State: ~/local-ai/shared/rentals/</p>`;
html += `</div>`;

// Build sent-mapping for tomorrow's feedback ingest: L# -> {url, title, description, price}
const sentMapping = {};
for (const l of scored) {
  sentMapping[l.tag] = {
    url: l.url,
    title: l.title,
    description: l.description,
    price: l.price,
    beds: l.beds,
    location: l.location,
  };
}

return [{ json: {
  subject: `🏠 Rental Watcher — ${scored.length} new — ${today}`,
  body_html: html,
  send: true,
  new_urls: scored.map(l => l.url),
  sent_date: today,
  sent_mapping: sentMapping,
} }];

// Update seen.json: merge today's URLs in, prune anything older than 60 days.
// Reads prior seen state from workflow static data (set by Dedup + Hard Filter).

const items = $input.all();
const staticData = $getWorkflowStaticData('node');
const prior = staticData.priorSeen || { urls: {} };

const newUrls = (items[0]?.json?.new_urls) || [];
const now = new Date().toISOString();

const seen = { urls: { ...(prior.urls || {}) } };
for (const u of newUrls) {
  if (!seen.urls[u]) seen.urls[u] = now;
}

const cutoff = new Date(Date.now() - 60 * 24 * 3600 * 1000).toISOString();
for (const [u, ts] of Object.entries(seen.urls)) {
  if (ts < cutoff) delete seen.urls[u];
}

const json = JSON.stringify(seen, null, 2);
return [{
  json: { count: Object.keys(seen.urls).length },
  binary: {
    data: {
      data: Buffer.from(json, 'utf8').toString('base64'),
      mimeType: 'application/json',
      fileName: 'seen.json'
    }
  }
}];

// Write today's L# -> listing mapping for tomorrow's feedback ingest.
const it = $input.first();
const date = it.json.sent_date;
const mapping = it.json.sent_mapping || {};

// Skip if no listings (no email sent → no mapping needed)
if (!date || Object.keys(mapping).length === 0) {
  return [];
}

const json = JSON.stringify({
  date,
  generated_at: new Date().toISOString(),
  mapping
}, null, 2);

return [{
  json: { date, count: Object.keys(mapping).length },
  binary: {
    data: {
      data: Buffer.from(json, 'utf8').toString('base64'),
      mimeType: 'application/json',
      fileName: `sent-${date}.json`
    }
  }
}];
